/* ---------- active tenant resolution ---------- */
const TENANT_STORAGE_KEY = 'nexstock-tenant';
function getActiveTenantId(){ const id = localStorage.getItem(TENANT_STORAGE_KEY); return (id && TENANTS[id]) ? id : 'nexstock'; }
function setActiveTenantId(id){ if (TENANTS[id]) localStorage.setItem(TENANT_STORAGE_KEY, id); }
const ACTIVE_TENANT_ID = getActiveTenantId();
const TENANT = TENANTS[ACTIVE_TENANT_ID];

/* ---------- globals rebuilt from the active tenant (keeps every page/script unchanged) ---------- */
const CATS = TENANT.cats;
function catMono(name){ return name.replace(/[^A-Za-z& ]/g,'').split(/[ ,&]+/).filter(Boolean).slice(0,2).map(w=>w[0]).join(''); }
const CAT_ICON = TENANT.catIcon;
const CAT_COLOR = TENANT.catColor;
const BRANDS_ALL = TENANT.brandsAll;
const PRODUCTS = TENANT.products;
function getProduct(id){ return PRODUCTS.find(p => p.id === Number(id)); }
const I18N = TENANT.i18n;
